fn digits(n: i32) -> i32 {
    let mut v: i32 = n;
    if v < 0 { v = 0 - v; }
    let mut c: i32 = 1;
    while v >= 10 {
        v = v / 10;
        c = c + 1;
    }
    c
}

fn pow10(k: i32) -> i32 {
    let mut p: i32 = 1;
    let mut i: i32 = 0;
    while i < k {
        p = p * 10;
        i = i + 1;
    }
    p
}

fn digit_at(n: i32, k: i32) -> i32 {
    let mut v: i32 = n;
    if v < 0 { v = 0 - v; }
    let d: i32 = v / pow10(k);
    d % 10
}

fn reverse(n: i32) -> i32 {
    let mut v: i32 = n;
    if v < 0 { v = 0 - v; }
    let mut r: i32 = 0;
    while v > 0 {
        r = r * 10 + v % 10;
        v = v / 10;
    }
    r
}

fn dims() -> i32 {
    (256 << 16) | 112
}

