    host::display::draw_number(8, 66, digits(90210), 0xffff00, 1);
    host::display::draw_number(60, 66, digit_at(90210, 2), 0xffff00, 1);
    host::display::draw_number(112, 66, reverse(90210), 0xffff00, 1);
    host::display::present();
}
